// Generated by esquadro: do not edit. Signing out after a time without
// use (the idle_minutes option): a warning a minute before, and any tab's
// use counts.
import { useQueryClient } from "@tanstack/react-query"
import { useNavigate } from "@tanstack/react-router"
import { useEffect, useState } from "react"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { base, idleMinutes } from "../config.ts"
import { signOut } from "./auth.tsx"
import { t } from "./i18n.ts"

const key = `esquadro:${base}:last-activity`
const WARN = 60_000

function lastActivity(): number {
  try {
    return Number(localStorage.getItem(key)) || Date.now()
  } catch {
    return Date.now()
  }
}

function touch() {
  try {
    localStorage.setItem(key, String(Date.now()))
  } catch {
    // Without storage, each tab keeps its own time.
  }
}

/** Watches for use, and signs out after idleMinutes without it. Once, in the signed-in layout. */
export function IdleTimeout({ minutes = idleMinutes }: { minutes?: number }) {
  const [warning, setWarning] = useState(false)
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  useEffect(() => {
    if (!minutes) return
    touch()
    let last = 0
    const used = () => {
      // At most once a second: mouse moves come by the hundred.
      if (Date.now() - last < 1000) return
      last = Date.now()
      touch()
      setWarning(false)
    }
    const events = ["mousemove", "keydown", "click", "scroll", "touchstart"]
    for (const e of events) window.addEventListener(e, used, { passive: true })
    const timer = setInterval(async () => {
      const idle = Date.now() - lastActivity()
      if (idle >= minutes * 60_000) {
        clearInterval(timer)
        const back = window.location.pathname.slice(base.length - 1) || "/"
        await signOut(queryClient)
        navigate({ to: "/login", search: { redirect: back } })
      } else {
        setWarning(idle >= minutes * 60_000 - WARN)
      }
    }, 5000)
    return () => {
      clearInterval(timer)
      for (const e of events) window.removeEventListener(e, used)
    }
  }, [minutes])
  if (!minutes) return null
  return (
    <AlertDialog open={warning}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{t("idleTitle")}</AlertDialogTitle>
          <AlertDialogDescription>{t("idleHint")}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogAction
            onClick={() => {
              touch()
              setWarning(false)
            }}
          >
            {t("stayConnected")}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}
